// Adapt pure engine to existing upload controls and diagnostics.
analyze=function(img){const scale=Math.min(160/img.naturalWidth,160/img.naturalHeight),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));canvas.width=w;canvas.height=h;ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);const out=FlowerEngine.analyze(ctx.getImageData(0,0,w,h).data,w,h,ENGINE_PROFILES,{minimumScore:Number($('scoreThreshold').value),minimumLead:Number($('marginThreshold').value)});for(const [name,id] of [['flower','maskPreview'],['leaf','leafMaskPreview'],['context','contextMaskPreview']]){const c=$(id);c.width=w;c.height=h;const cctx=c.getContext('2d'),pixels=cctx.createImageData(w,h);for(let p=0;p<w*h;p++){const value=out.masks[name][p]?255:18;pixels.data.set([value,value,value,255],p*4)}cctx.putImageData(pixels,0,0)}delete out.masks;return out};
render=function(out){lastOutput=out;const top=out.candidates[0],usable=out.quality.usable;$('prediction').textContent=usable?top.name:'NO RELIABLE REGION';$('latin').textContent=usable?top.latin:'—';$('growthStage').textContent='Unknown'+(usable?' · hypothesis: '+top.stage:'');$('plantPart').textContent=usable?top.part:'—';$('decision').textContent='REVIEW REQUIRED';$('topScore').textContent=top.score.toFixed(3);$('leadScore').textContent=out.decision.lead.toFixed(3);$('runStatus').textContent='EXPERIMENTAL';$('runStatus').className='status idle';$('decisionLog').textContent=out.decision.reason;
const categories={COLOUR:['pink','red','yellow','blue','pale'],SHAPE:['fill','flower_coverage'],CENTRE:['center_yellow','outer_yellow'],SURFACE:['texture','color_diversity'],CONTEXT:['vegetation_coverage']};$('featureRows').innerHTML=Object.entries(categories).map(([title,keys])=>`<section class="feature-group"><h3>${title}</h3>${keys.map(key=>{const value=out.features[key];return `<div class="feature-item"><div class="feature-label"><span>${key.replaceAll('_',' ')}</span><strong>${value==null?'N/A':value.toFixed(3)}</strong></div><div class="bar"><span style="width:${(value||0)*100}%"></span></div></div>`}).join('')}</section>`).join('');
document.querySelector('.candidates thead').innerHTML='<tr><th>#</th><th>Candidate / stage hypothesis</th><th>Colour</th><th>Shape</th><th>Centre</th><th>Surface</th><th>Fit</th></tr>';
$('candidateRows').innerHTML=out.candidates.map(row=>`<tr><td>${row.rank}</td><td>${row.name}<br><small>${row.stage} · ${row.taxonRank}</small></td>${['colour','shape','centre','surface'].map(k=>`<td>${row.parts[k]==null?'—':row.parts[k].toFixed(2)}</td>`).join('')}<td>${row.score.toFixed(3)}</td></tr>`).join('');
const strengths=top.evidence.filter(e=>!e.contradiction),conflicts=top.evidence.filter(e=>e.contradiction);$('rawOutput').textContent=`CANDIDATE EVIDENCE — ${top.name}\nThese are experimental feature ranges, not botanical proof.\n\nMATCHED\n${strengths.map(e=>`${e.feature}: ${e.value.toFixed(3)} in [${e.expected.join(', ')}]`).join('\n')}\n\nCONFLICTS\n${conflicts.map(e=>`${e.feature}: ${e.value.toFixed(3)} outside [${e.expected.join(', ')}]`).join('\n')||'None among measured features'}\n\nUNMEASURED\nPetal count, flower tubes, bracts, reproductive column, leaf arrangement.\n\nRAW OUTPUT\n${JSON.stringify(out,null,2)}`;$('copyButton').disabled=false;};
document.querySelector('.candidates .panel-head h2').textContent='EXPERIMENTAL CANDIDATES';document.querySelector('.candidates .panel-head span').textContent='4 feature groups · uncalibrated fit, not probability';document.querySelector('.raw h2').textContent='EVIDENCE / RAW OUTPUT';document.querySelector('.features .panel-head span').textContent='flower region only, except context';
